use vstd::prelude::*;

verus! {

fn concat(a: &Vec<u64>, b: &Vec<u64>) -> (res: Vec<u64>)
    requires
        a.len() <= 100,
        b.len() <= 100,
    ensures
        res.len() == a.len() + b.len(),
        forall|i: int| 0 <= i < a.len() ==> res[i] == a[i],
        forall|i: int| a.len() <= i < res.len() ==> res[i] == b[i - a.len()],
{
    let mut res: Vec<u64> = Vec::new();

    // Copy elements of a
    let mut i: usize = 0;
    while i < a.len()
        invariant
            a.len() <= 100,
            b.len() <= 100,
            i <= a.len(),
            res.len() == i,
            forall|k: int| 0 <= k < i ==> res[k] == a[k],
        decreases a.len() - i,
    {
        res.push(a[i]);
        i = i + 1;
    }

    // Copy elements of b
    let mut j: usize = 0;
    while j < b.len()
        invariant
            a.len() <= 100,
            b.len() <= 100,
            j <= b.len(),
            res.len() == a.len() + j,
            forall|k: int| 0 <= k < a.len() ==> res[k] == a[k],
            forall|k: int| a.len() <= k < res.len() ==> res[k] == b[k - a.len()],
        decreases b.len() - j,
    {
        res.push(b[j]);
        j = j + 1;
    }

    res
}

} // verus!

